	cmp		ecx, r8d
	jae		.n_left
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_LEFT
.n_left:
	cmp		r8d, r9d
	ja		rest				; no friend (255), or the poorest is above the limit
	ret					; al = ACT_FEED + direction

feed_up:
	mov		al, ACT_FEED + DIR_UP
	ret
feed_right:
	mov		al, ACT_FEED + DIR_RIGHT
	ret
feed_down:
	mov		al, ACT_FEED + DIR_DOWN
	ret
feed_left:
	mov		al, ACT_FEED + DIR_LEFT
	ret

; ---- constants (legacy-SSE memory operands must be 16-byte aligned)
	align 16
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes (window idx 7..22)
kRefill:	db 0x02, 0x00, 0x02, 0xff, 0x02, 0x00, 0xff, 0x00, 0x02, 0xff, 0x02, 0x00, 0x02, 0xff, 0xff, 0xff	; window idx 6..21: 0 at neighbours, 2 at 6/8/10/14/16/18
kZero:	times 16 db 0
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded
kNearLo:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff	; idx 0..15: 2 at 6 and 8
kNearHi:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff	; idx 9..24: 2 at 16 and 18
kRingE1:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff	; idx 0..15: 2 at 6, 8, 10, 14
kRingE2:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff	; idx 9..24: 2 at 16, 18, 22
kRingZ1:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x00, 0xff, 0x00, 0xff, 0x00, 0xff, 0xff, 0xff, 0x00, 0xff	; idx 0..15: 0 at 6, 8, 10, 14
kRingZ2:	db 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x00, 0xff, 0x00, 0xff, 0xff, 0xff, 0x00, 0xff, 0xff	; idx 9..24: 0 at 16, 18, 22
kOne:	times 16 db 1		; friend lanes
dir_idx:	db 7, 13, 17, 11	; view index of the neighbour UP, RIGHT, DOWN, LEFT
dir_tbl:	db 71, 77, 81, 75	; view offset of the energy of the neighbour UP, RIGHT, DOWN, LEFT
arm_tbl:			; jump target per direction (rax = ACT_EAT + d)
	dq arm_up, arm_right, arm_down, arm_left
k16_tbl:			; pattern row offset k * 16 by te (te 0..255)
	db 0,0,0,16,16,32,32,48,48,64,64,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80
	db 0,0,0,16,16,32,32,48,48,64,64,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80
	db 0,0,0,16,16,32,32,48,48,64,64,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80
	db 0,0,0,16,16,32,32,48,48,64,64,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80,80
pat1_tbl:			; 16-byte rows (d, k): slots e0 - 4 .. e0 + 11 (k = 0: e0 - 4, e0 - 2, e0)
	db 0x30, 0x00, 0x30, 0x00, 0x30, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00	; d 0, k 0
	db 0x30, 0x00, 0x30, 0x00, 0x30, 0x00, 0x30, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00	; d 0, k 1
